answer:
There isn't a native way with Klout's UI that I am aware of. Your best bet is finding a Chrome Extension that handles Facebook JS SDK API calls, then you can do something like this

FB.api('/me/apprequests', function(response) {
  var ids = [];
  for (var i=0, l=response.data.length; i&lt;l; i++) {
    FB.api('/' + response.data[i].id, 'DELETE', 
      function(response){ console.log('cleared request:' + response) } 
    );
    console.log('For: ' + response.data[i].to.name);
  }
});


Quick and dirty would be to just paste this into your Developer console on Klout's page.

