( ISPICKVAL(LeadSource, 'Trade Show/Event') &amp;&amp; ISBLANK(TextField__c)
) ||
/* check TBP */
( ISPICKVAL(LeadSource, 'TBP Event') &amp;&amp; ISBLANK(TextField__c)
) ||
