-(UserData*)getUserForUserid:(NSString *)user_id
{
    NSFetchRequest *request = [self getBasicRequestForEntityName:@"UserData"];
    NSPredicate *predicate = [NSPredicate predicateWithFormat:@"user_id== %@",user_id];


    [request setPredicate:predicate];
    [request setReturnsObjectsAsFaults:NO];

    NSError *error = nil;
    NSArray *results = [managedObjectContext executeFetchRequest:request error:&amp;error];  

    UserData *userInfoObj = nil;
    if (!error &amp;&amp; [results count] &gt; 0)
    {

        userInfoObj = [results objectAtIndex:0];

    }

    return userInfoObj;
}

question_body:
The following code only prints "good". Why the generator function is not executed?
I noticed with pdb that after executing 'handlers1' the script reaches the line with f1's definition but then does not get inside the function. Conversely, it's returned 'GeneratorExit: None'.

class foo:

   def f0(self, s):
      print s

   def f1(self, s):
      print "not " + s
      yield 1

   def run(self):
      handlers={0 : self.f0, 1 : self.f1}
      handlers[0]('good')
      handlers[1]('good')

bar = foo()
bar.run()


Why this happens? Is it possible to call generator functions in a similar dynamic way?

answer:
You need to call next or the code in the generator won't run at all.

class foo:

   def f0(self, s):
      print s

   def f1(self, s):
      print "not " + s
      yield 1

   def run(self):
      handlers={0 : self.f0, 1 : self.f1}
      handlers[0]('good')
      handlers[1]('good').next()

bar = foo()
bar.run()


That prints "good" then "not good".

