     if(isAVowel){
         vowels++;
     }else if(isAVowel &amp;&amp; y){
     vowels++;
    consonants++;
//}else if(y &amp;&amp; !(isAVowel)){
//   vowels++;
      }else{
      consonants++;
      }


System.out.println("The number of vowels in \"" +phrase+"\" is "+ vowels+".\n\nThe number of consonants is "+consonants+".\n\n");


When "y" is by itself it says its a consonant, it should be a vowel. Where do I state this?

answer:
The following recursive function returns the number of vowels in an input string

public static int vc(String s){
    if(s.length() - 1 &lt; 0) return 0;
    return ((("aeiou".indexOf((s.charAt(s.length()-1)+"").toLowerCase()) &gt;= 0 ? 1 : 0))  
    + vc((s = s.substring(0,s.length()-1))));
}

