    &lt;tbody data-bind="foreach: orders"&gt;
        &lt;tr&gt;
            &lt;td data-bind="text: Name"&gt;&lt;/td&gt;
            &lt;td&gt;&lt;input type="number" style="width: 100px;" data-bind="value: Price" /&gt;&lt;/td&gt;
