XDocument someXmlDoc = XDocument.Create(fileName);
IEnumerable&lt;XElement&gt; widthElements = someXmlDoc.Descendants("Width");
int[] widthValues = widthElements.Select(xelement =&gt; int.Parse(xelement.Value)).ToArray();


